#!/usr/bin/env python3
import sys

YES = "Yes"  # type: str
NO = "No"  # type: str


def solve(S: str):
    def pe(string): return string.find(string[::-1])
    if pe(S)==-1:
        print(NO)
    else:
        o=S[:int(((len(S)-1)/2))]
        if pe(o)==-1:
            print(NO)
        else:
            u=S[int((len(S)+3)/2)-1:len(S)]
            if pe(u)==-1:
                print(NO)
            else:
                print(YES)
    return


# Generated by 1.1.6 https://github.com/kyuridenamida/atcoder-tools  (tips: You use the default template now. You can remove this line by using your custom template)
def main():
    def iterate_tokens():
        for line in sys.stdin:
            for word in line.split():
                yield word
    tokens = iterate_tokens()
    S = next(tokens)  # type: str
    solve(S)

if __name__ == '__main__':
    main()
